/* Standalone design prototype. No application ledger, storage or cloud code is loaded. */
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₹'+Number(n).toLocaleString('en-IN',{maximumFractionDigits:2}),signed=n=>(n>=0?'+':'−')+money(Math.abs(n));
const paths={settings:'M4 7h16M4 17h16M8 4v6m8 4v6',back:'m14 5-7 7 7 7',arrow:'M4 12h16m-6-6 6 6-6 6',home:'M3 10 12 3l9 7v10H3Zm6 10v-7h6v7',table:'M7 5h10a4 4 0 0 1 4 4v6a4 4 0 0 1-4 4H7a4 4 0 0 1-4-4V9a4 4 0 0 1 4-4ZM7 9h10M7 13h5',players:'M15 20v-3a6 6 0 0 0-12 0v3m15-7a5 5 0 0 1 3 5v2M9 10a3 3 0 1 0 0-6 3 3 0 0 0 0 6Zm8-6a3 3 0 0 1 0 6',history:'M3 11a9 9 0 1 1 2 7M3 4v7h7m2-4v6l4 2',chart:'M4 20h16M7 15V9m5 6V4m5 11V8',check:'m5 12 4 4L19 6',clock:'M12 7v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6Z',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',cup:'M7 3h10v7a5 5 0 0 1-10 0Zm0 2H3v4a5 5 0 0 0 5 5M17 5h4v4a5 5 0 0 1-5 5M12 15v6m-5 0h10',more:'M5 12h.01M12 12h.01M19 12h.01',plus:'M12 4v16M4 12h16',receipt:'M5 3h14v18l-3-2-4 2-4-2-3 2ZM8 7h8M8 11h8M8 15h4'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.arrow}" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const link=(text,route,cls='')=>`<a class="button ${cls}" href="#${route}">${text}</a>`;
const button=(text,action,cls='',attrs='')=>`<button type="button" class="button ${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const head=(title,subtitle='',back='home')=>`${back?`<a class="back" href="#${back}">${icon('back')}${back==='home'?'Home':back==='table'?'Table':back==='tournament'?'Tournament':'Back'}</a>`:''}<header class="page-heading"><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</header>`;
const avatar=p=>`<span class="avatar">${esc(p.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span>`;
const identity=(p,sub='')=>`<div class="identity">${avatar(p)}<div class="grow"><div class="name">${esc(p.name)}</div>${sub?`<small>${sub}</small>`:''}</div></div>`;
const detail=(label,value,cls='')=>`<div class="detail ${cls}"><span>${label}</span><strong>${value}</strong></div>`;
const notice=(text,cls='')=>`<div class="notice ${cls}">${text}</div>`;
let toastTimer;function toast(t,success=false){if(window.CashMotionLibrary)CashMotionLibrary.announce(t,success);else $('#toast').textContent=t;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',4000)}
const contacts=['Alex Morgan','Jamie Chen','Sam Rivera','Taylor Reed','Jordan Patel','Casey Brooks','Morgan Lee','Riley Shah','Avery Singh','Quinn Parker','Drew Wilson','Cameron Ali','Skyler Kim','Robin Das','Charlie Evans'].map((name,i)=>({id:i+1,name,last:5000}));
const now=Date.now();let minimumHours=3,tableName='Friday Night',tableClosed=false,filter='all',profileId=1,receiptId='jamie',receiptBack='settlement',transferPaid=false,restored=false,editPlayerId=null;
let tableBanker={id:'host',name:'',phone:''};
let players=contacts.slice(0,4).map((p,i)=>({...p,buy:5000,out:[null,null,7200,3800][i],received:i===1?3000:5000,paid:i===3?3800:0,firstBuy:now-[40,190,200,220][i]*60000,minimum:180*60000}));
let rakeTotal=300,tableQuery='',tableSort='name',rakeDraft='200',lastDesignEntry=null,currentReceiptPlayerId=3,shareContext='receipt';
let tournamentConfig={name:'Friday Cup',chips:20000,entry:1500,minutes:20,seats:9,cutoff:'Level 4'};
let amountDraft={kind:'buy',id:4,amount:'',received:'',reason:''},cashDraft={id:1,amount:'',override:false};
let tx=[{name:'Alex Morgan',time:'19:30',title:'Initial buy-in',amount:5000},{name:'Jamie Chen',time:'20:00',title:'Initial buy-in',amount:5000},{name:'Sam Rivera',time:'17:00',title:'Initial buy-in',amount:5000}];
const receiptPlayers={jamie:{name:'Jamie Chen',buy:9000,out:11200,received:9000,paid:5000,entries:[['19:00 · Buy-in',5000],['20:10 · Rebuy',2000],['21:05 · Rebuy',2000]]},alex:{name:'Alex Morgan',buy:5000,out:3000,received:5000,paid:0,entries:[['19:30 · Buy-in',5000]]},sam:{name:'Sam Rivera',buy:5000,out:3000,received:0,paid:0,entries:[['18:00 · Buy-in',5000]]},jordan:{name:'Jordan Patel',buy:5000,out:0,received:5000,paid:0,entries:[['20:00 · Buy-in',5000]]}};
const groups={
'Home & cash tables':[['home','Home'],['new-table','Create cash table'],['table','Running table'],['table-settings','Table settings'],['add-player','Add player to table']],
'Money & safeguards':[['buy-in','Buy-in / rebuy'],['amount-review','Review buy-in'],['cash-out','Enter cash-out'],['cash-out-review','Review cash-out'],['early-exit','Early-profit warning'],['correction','Correct recorded amount'],['review','Review & close table'],['activity','Transaction activity']],
'Players & history':[['players','Saved players'],['new-player','New / edit player'],['player','Player profile'],['history','Past tables'],['history-detail','Past table results'],['insights','Game-night insights']],
'Settlement & receipts':[['settlement','Who pays whom'],['payment','Record a payment'],['payments','Payments & corrections'],['receipt','Past player receipt'],['current-receipt','Current player receipt']],
'One-table tournament':[['tournament-setup','Start tournament'],['tournament-review','Review tournament rules'],['tournament-structure','Blind structure'],['tournament','Live tournament'],['tournament-players','Entrants & seats'],['tournament-entry','Entry / rebuy / add-on'],['tournament-elimination','Record elimination'],['tournament-payouts','Prize pool & payouts'],['tournament-results','Final standings']],
'Settings & recovery':[['settings','Settings'],['cloud','Cloud backup'],['restore','Choose restore file'],['restore-review','Review restore'],['install','Install app'],['privacy','Privacy & recovery']],
'Entry & recovery states':[['rake-entry','Add rake'],['rake-review','Review rake'],['share-preview','Share preview'],['csv-import','Import CSV · phase 2'],['save-pending','Saving entry'],['save-error','Entry not saved'],['save-success','Entry recorded'],['empty-table','Empty table']],
'Design system':[['components','Reusable components']]};
const routeMeta=Object.entries(groups).flatMap(([group,rs])=>rs.map(([id,label])=>({id,label,group})));
const contexts={home:'The starting point for cash games and tournaments. Both actions are visible before scrolling.',table:'Call-time badges sit beside names. Each deadline uses that player’s own first confirmed buy-in. The default minimum is 3 hours.',receipt:'Profit or loss is distinct from remaining payment. Switch between real player identities to inspect all receipt outcomes.', 'early-exit':'Early profitable exits are advisory, with a house-exception path into the normal final review. No forced payout.',insights:'Phase-2 presentation and required collection fields. Completed sessions, source values and timing completeness stay explicit.',cloud:'Production-facing connection flow; live provider setup remains an implementation/release gate.'};
let currentRoute='home',activeInfo=false;function go(route){if(location.hash==='#'+route)render();else location.hash=route}
function person(){return players.find(p=>p.id===cashDraft.id)||players[0]}
function balance(){const buy=players.reduce((s,p)=>s+p.buy,0),out=players.reduce((s,p)=>s+(p.out||0),0),pending=players.filter(p=>p.out===null);return{buy,out,pending,difference:buy-out-rakeTotal}}
const chipArt=`<svg class="hero-art" viewBox="0 0 120 120" aria-hidden="true"><g fill="none" stroke="currentColor"><circle cx="60" cy="60" r="54"/><circle cx="60" cy="60" r="42"/><circle cx="60" cy="60" r="32"/><path d="M60 6v13m0 82v13M6 60h13m82 0h13M22 22l9 9m58 58 9 9M22 98l9-9m58-58 9-9"/></g></svg>`;
function hero(label,value,footer=''){return `<section class="hero">${chipArt}<span class="eyebrow">${label}</span><div class="amount">${value}</div>${footer}</section>`}
function clockFor(p){const left=Math.max(0,Math.ceil((p.firstBuy+p.minimum-Date.now())/1000));return{left,met:left===0,text:String(Math.floor(left/3600)).padStart(2,'0')+':'+String(Math.floor(left%3600/60)).padStart(2,'0')+':'+String(left%60).padStart(2,'0')}}
function bankerFields(){return `<fieldset class="banker-fields"><legend>Banker details</legend><p class="small">Shown by name on this table’s receipts. Phone stays private.</p><div class="field"><label for="banker">Choose banker</label><select id="banker"><option value="host" ${tableBanker.id==='host'?'selected':''}>Me / host</option>${contacts.filter(p=>!p.archived).map(p=>`<option value="${p.id}" ${String(p.id)===tableBanker.id?'selected':''}>${esc(p.name)}</option>`).join('')}<option value="custom" ${tableBanker.id==='custom'?'selected':''}>Someone else</option></select></div><div class="field"><label for="banker-name">Banker’s full name</label><input id="banker-name" autocomplete="name" maxlength="80" value="${esc(tableBanker.name)}" placeholder="Full name on receipts" required></div><div class="field"><label for="banker-phone">Phone number <span class="small">· optional</span></label><input id="banker-phone" type="tel" autocomplete="tel" maxlength="30" value="${esc(tableBanker.phone)}" placeholder="Not included on receipts"></div></fieldset>`}
function readBanker(){const name=$('#banker-name').value.trim();if(!name){$('#banker-name').focus();return null}return {id:$('#banker').value,name,phone:$('#banker-phone').value.trim()}}
function newTable(){if(!tableClosed&&players.length){const b=balance();return head('A table is already running','Finish this table before starting another.')+`<section class="card table-start-blocked" aria-labelledby="active-table-title"><span class="eyebrow">CURRENT CASH TABLE</span><h2 id="active-table-title">${esc(tableName)}</h2>${detail('Stacks still to enter',String(b.pending.length))}${!b.pending.length?detail('Balance difference',money(b.difference)):''}<p>Keep every buy-in and payment intact. Review the current table before closing it.</p><div class="actions">${link('Return to table','table','primary')}${link('Review & close','review')}</div></section><p class="hint">Completed tables and outstanding payments stay in history.</p>`}return head('Create a cash table','Private by default.')+`<form data-form="new-table"><div class="field"><label for="table-name">Table name</label><input id="table-name" maxlength="60" placeholder="Friday Night" required></div>${bankerFields()}<div class="field"><label for="minimum-new">Minimum play · hours</label><input id="minimum-new" type="number" min="0" max="24" step="0.25" value="3" required><p class="small">Each player starts their own clock when their buy-in is confirmed.</p></div><div class="actions"><button class="button primary" type="submit">Create private table</button></div></form>`}

function tableSettings(){return head('Table settings',esc(tableName),'table')+`<form data-form="table-settings">${bankerFields()}<div class="field"><label for="minimum-hours">Minimum play · hours</label><input id="minimum-hours" type="number" min="0" max="24" step="0.25" value="${minimumHours}" required></div><p class="small">Default: 3 hours. Zero disables the rule for new buy-ins.</p>${notice('Each player has an independent clock. Rebuys do not restart it. Before call time, profitable exits require a house-exception confirmation.')}${notice('Changes apply to new buy-ins. Existing players keep their recorded minimum and start time.')}<div class="two"><div class="field"><label for="small-blind">Small blind · ₹</label><input id="small-blind" type="number" min="1" value="50" required></div><div class="field"><label for="big-blind">Big blind · ₹</label><input id="big-blind" type="number" min="1" value="100" required></div></div><p class="small">Stakes describe the game. Buy-ins and cash-outs remain cash amounts.</p><div class="actions"><button class="button primary" type="submit">Save settings</button></div></form>`}
function roster(seating=false){return head(seating?'Add a player':'Your players',seating?'Search saved players by name or phone.':'Familiar faces. A fresh table.',seating?'table':'home')+`<label for="player-search" class="small">Search saved players</label><input id="player-search" type="search" placeholder="Name or phone"><div id="roster-results" style="margin-top:15px">${rosterRows('',seating)}</div><div class="actions">${link('+ Create new player','new-player','primary')}</div>`}
function rosterRows(query='',seating=false){const list=contacts.filter(p=>!p.archived&&p.name.toLowerCase().includes(query.toLowerCase()));return list.map(p=>`<div class="list-row">${avatar(p)}<div class="grow"><strong>${p.name}</strong><small>${p.phone||'No phone number added'}</small></div>${seating?players.some(x=>x.id===p.id)?'<span class="tag">Seated</span>':button('Add','seat','compact',`data-id="${p.id}"`):button(icon('arrow'),'profile','compact',`data-id="${p.id}" aria-label="Open ${p.name}"`)}</div>`).join('')||notice('No matching players. Try another name.')}
function playerForm(){const editing=contacts.find(p=>p.id===editPlayerId);return head(editing?'Edit player':'New player','Saved only to your private records.','players')+`<form data-form="player"><div class="field"><label for="player-name">Name</label><input id="player-name" maxlength="60" required value="${esc(editing?.name||'')}"></div><div class="field"><label for="player-phone">Phone number · optional</label><input id="player-phone" type="tel" maxlength="60" value="${esc(editing?.phone||'')}"></div><div class="field"><label for="player-photo">Photo · optional</label><input id="player-photo" type="file" accept="image/png,image/jpeg,image/webp"></div>${notice('Similar names and phone numbers are checked before creating a duplicate. Player identity stays stable if their details change.')}<div class="actions"><button class="button primary" type="submit">Save player</button></div></form>`}
const profileSessions=[4800,-3000,8200,-5600,3800,2600,-4200,6200,-3600,3200].map((net,i)=>({net,date:['09 Oct','12 Oct','15 Oct','18 Oct','21 Oct','24 Oct','27 Oct','30 Oct','03 Nov','06 Nov'][i],name:['Friday Regulars','Midweek Mix','After Hours','Sunday Session','Saturday Regulars'][i%5]}));
let profileTab='overview',profileSession=9;
function statCard(label,value,caption,tone=''){return `<section class="stat spectrum-stat"><div class="stat-label">${label}</div><strong class="${tone}">${value}</strong><small>${caption}</small></section>`}
function profileTabs(key='Player profile'){return `<div class="segment profile-segment" aria-label="${key}">${['overview','sessions'].map(t=>`<button class="${profileTab===t?'selected':''}" data-action="profile-tab" data-value="${t}" aria-pressed="${profileTab===t}">${t==='overview'?'Overview':'Sessions'}${t==='sessions'?'<span class="tab-count">10</span>':''}</button>`).join('')}</div>`}
function profileTrend(){let running=0;const totals=profileSessions.map(s=>running+=s.net),points=totals.map((v,i)=>`${12+i*34},${112-v/14000*90}`),selected=profileSessions[profileSession];return `<section class="card profile-trend"><div class="row"><div><h3>Result over time</h3><small>Completed cash sessions</small></div><span class="tag">10 sessions</span></div><svg class="chart" viewBox="0 0 330 130" role="img" aria-label="Cumulative results across ten completed sessions, from positive 4,800 to positive 12,400 rupees"><path class="grid" d="M12 112H318M12 67H318M12 22H318"/><path d="M12 112 ${points.map(p=>'L'+p).join(' ')} L318 112Z" fill="var(--ambient)"/><path class="line" d="M${points.join(' L')}"/><circle cx="${12+profileSession*34}" cy="${112-totals[profileSession]/14000*90}" r="5" fill="var(--green)" stroke="var(--surface)" stroke-width="3"/></svg><div class="row"><small>09 Oct</small><small>06 Nov</small></div><label for="session-inspector" class="sr-only">Inspect completed session</label><input id="session-inspector" class="session-slider" type="range" min="0" max="9" step="1" value="${profileSession}" aria-valuetext="${selected.date}, session result ${signed(selected.net)}, cumulative ${signed(totals[profileSession])}"><div class="session-readout" id="session-readout" aria-live="polite"><div><strong>${selected.date} · ${selected.name}</strong><small>Session ${profileSession+1} of 10</small></div><div class="readout-money"><strong class="${selected.net>=0?'positive':'negative'}">${signed(selected.net)}</strong><small>${signed(totals[profileSession])} cumulative</small></div></div><p class="small chart-hint">Drag or use the arrow keys to inspect a session.</p></section>`}
function profileSessionRows(){return `<div class="session-list">${[...profileSessions].reverse().map((s,i)=>`<a class="list-row" href="#history-detail"><span class="session-mark ${s.net>=0?'win':'loss'}" aria-hidden="true">${s.net>=0?'↗':'↘'}</span><div class="grow"><strong>${s.name}</strong><small>${s.date} 2026 · cash game</small></div><div class="session-result"><strong class="${s.net>=0?'positive':'negative'}">${signed(s.net)}</strong><small>${s.net>=0?'Won':'Lost'}</small></div></a>`).join('')}</div>`}
function profile(){const p=contacts.find(p=>p.id===profileId)||contacts[0],seated=players.some(x=>x.id===p.id);return head('Player profile','','players')+`<div class="profile-identity"><div class="identity"><span class="avatar large">${esc(p.name.split(' ').map(n=>n[0]).join(''))}</span><div><span class="eyebrow">Your roster</span><h2>${esc(p.name)}</h2><small>${esc(p.phone||'Phone number not added')}</small></div></div>${button(icon('settings'),'edit-player','compact',`data-id="${p.id}" aria-label="Edit ${esc(p.name)}"`)}</div><section class="profile-result magic-card"><div class="row"><span class="eyebrow">Net poker result</span><span class="result-seal">${icon('check')} Completed sessions</span></div><div class="amount positive">+₹12,400</div><p class="small">Across 10 cash-game sessions</p><div class="profile-summary"><div><strong>10</strong><small>Sessions</small></div><div><strong>60%</strong><small>Win rate</small></div><div><strong>6 <span>/ 4</span></strong><small>Wins / losses</small></div></div></section>${profileTabs()}${profileTab==='overview'?`${profileTrend()}<div class="section-head"><h2>By the numbers</h2></div><div class="two stats-grid">${statCard('Average win','+₹4,800','6 winning sessions','positive')}${statCard('Average loss','−₹4,100','4 losing sessions','negative')}${statCard('Biggest win','+₹8,200','15 Oct · After Hours','positive')}${statCard('Biggest loss','−₹5,600','18 Oct · Sunday Session','negative')}</div><div class="card profile-buyin">${detail('Average buy-in','₹10,000')}${detail('Total buy-ins','₹1,00,000')}<small>Includes initial buy-ins and rebuys per session.</small></div><p class="small profile-footnote">Win/loss averages use matching sessions only. Live stacks and payment timing do not change poker results.</p>`:`<div class="row section-head"><h2>Completed sessions</h2><span class="tag">Latest first</span></div>${profileSessionRows()}`}
<div class="actions">${seated?'<button class="button primary" disabled>Already at this table</button>':button('+ Add to table','seat','primary',`data-id="${p.id}"`)}</div><details class="player-options"><summary>Player options</summary><div class="stack">${button('Edit player','edit-player','',`data-id="${p.id}"`)}${button('Archive player','archive','danger',`data-id="${p.id}"`)}</div><p class="small">Archiving keeps current seats, past results and payment records.</p></details>`}

function amountPage(){const p=contacts.find(p=>p.id===amountDraft.id)||contacts[3],edit=amountDraft.kind==='correction';return head(edit?'Correct buy-in':amountDraft.kind==='rebuy'?'Add money':amountDraft.kind==='reentry'?'Return to play':'Initial buy-in',esc(p.name),'table')+identity(p,edit?'Actual payments remain unchanged.':'Review the amount before recording.')+`<form data-form="amount"><div class="field"><label for="amount">${edit?'Corrected buy-in total':'Cash amount'} · ₹</label><input class="number-input" id="amount" inputmode="decimal" type="text" autocomplete="off" value="${esc(amountDraft.amount)}" placeholder="0" required></div><div class="shortcut">${button('+ '+money(p.last),'shortcut','compact',`data-value="${p.last}"`)}${button('+ ₹1,000','shortcut','compact','data-value="1000"')}${button('Clear','clear','compact')}</div>${keypad()}${edit?`<div class="field"><label for="reason">Reason for correction</label><input id="reason" minlength="3" maxlength="160" required value="${esc(amountDraft.reason)}"></div>`:`<fieldset class="field"><legend>Has this money been received?</legend><label class="check"><input type="radio" name="received" value="yes" ${amountDraft.received==='yes'?'checked':''} required> Received now</label><label class="check"><input type="radio" name="received" value="no" ${amountDraft.received==='no'?'checked':''}> Not yet · track as due</label></fieldset>`}<p id="amount-error" class="negative small" role="alert"></p><div class="actions"><button class="button primary" type="submit">Review amount</button></div><p class="hint">Shortcut taps add to this draft. Nothing is recorded yet.</p></form>`}
function keypad(){return `<div class="keypad" aria-label="Cash amount keypad">${['1','2','3','4','5','6','7','8','9','.','0','⌫'].map(k=>button(k,'key','',`data-value="${k}" aria-label="${k==='⌫'?'Backspace':k==='.'?'Decimal point':k}"`)).join('')}</div>`}
function amountReview(){const p=players.find(p=>p.id===amountDraft.id),n=Number(amountDraft.amount)||2000,total=amountDraft.kind==='correction'?n:(p?.buy||0)+n;return head('Check before recording',esc((p||contacts.find(p=>p.id===amountDraft.id))?.name||'Taylor Reed'),'buy-in')+hero(amountDraft.kind==='correction'?'Corrected buy-in total':'Additional buy-in',money(n))+`<section class="card" style="margin-top:16px">${detail('Table',esc(tableName))}${detail('Recorded so far',money(p?.buy||0))}${detail('After this entry',money(total))}${detail('Payment',amountDraft.kind==='correction'?'Unchanged':amountDraft.received==='no'?'Not received · due':'Received now')}${amountDraft.kind==='correction'?detail('Correction reason',esc(amountDraft.reason)):''}</section>${notice(amountDraft.kind==='buy'?'Confirming this buy-in starts this player’s own 3-hour call-time clock.':'The original call-time clock is preserved.')}<div class="actions">${button('Record '+money(n)+(amountDraft.kind==='correction'?' corrected total':amountDraft.kind==='buy'?' buy-in':' rebuy'),'confirm-amount','primary')}${link('Edit amount','buy-in')}</div>`}
function cashout(){const p=person();return head(p.out===null?'Cash out':'Correct cash-out',esc(p.name),'table')+identity(p,`Total buy-in ${money(p.buy)}`)+`<form data-form="cashout"><div class="field"><label for="cash-stack">Remaining stack · ₹</label><input class="number-input" id="cash-stack" inputmode="decimal" type="text" placeholder="0" value="${esc(cashDraft.amount)}" required></div>${keypad()}${notice('Enter the whole remaining stack, not the profit. Zero is a valid stack. Recording it does not mark money as paid.')}<p class="negative small" id="cash-error" role="alert"></p><div class="actions"><button class="button primary" type="submit">Review cash-out</button></div></form>`}
function cashReview(early=false){const p=person(),n=Number(cashDraft.amount)||0,c=clockFor(p),net=(p.priorOut||0)+n-p.buy;if(early)return cashReview(false)+`<dialog id="early-exit-dialog" class="product-modal" aria-labelledby="early-exit-title"><div class="eyebrow negative">Call time pending</div><h2 id="early-exit-title">Leaving early in profit?</h2><p>${esc(p.name)} has not completed the minimum play time.</p><section class="card" style="margin-top:18px">${detail('Time remaining',c.text)}${detail('Minimum play','3 hours')}${detail('Proposed cash-out',money(n))}${detail('Poker result',signed(net))}</section>${notice('You can make an exception for this house game. The acknowledgement stays in the activity history.')}<div class="actions">${link('Keep playing','table','primary')}${button('Cash out anyway · house exception','allow-early')}</div><p class="hint">Next: final review. No automatic payout.</p></dialog>`;const clockLabel=cashDraft.override?'House exception acknowledged':c.met?'Minimum met':net<=0?'Early exit · no profit':c.text+' left';return head('Confirm cash-out','','cash-out')+`<section class="card cash-review-card" aria-label="Cash-out for ${esc(p.name)}"><header class="cash-review-person">${identity(p)}<span class="cash-review-clock ${cashDraft.override?'exception':c.met?'met':'pending'}">${icon('clock')}<span>Call time · ${clockLabel}</span></span></header><div class="cash-review-stack"><span>${p.priorOut?'This cash-out':'Stack to cash out'}</span><strong>${money(n)}</strong></div><dl class="cash-review-metrics"><div><dt>Total buy-ins</dt><dd>${money(p.buy)}</dd></div><div><dt>Poker result</dt><dd class="${net>0?'positive':net<0?'negative':''}">${net===0?'₹0 · Break-even':signed(net)}</dd></div></dl>${p.priorOut?`<div class="cash-review-prior">${detail('Previous cash-outs',money(p.priorOut))}</div>`:''}</section><p class="cash-review-note">${icon('receipt')}<span>${n===0?'₹0 records an empty stack. ':''}Stack recorded only. Payout stays separate.</span></p><div class="cash-review-actions">${button('Record '+money(n)+' stack','confirm-cashout','primary')}${link('Edit stack','cash-out')}</div>`}

function activity(){return head('Table activity','Every confirmed change stays traceable.','table')+`<div class="timeline">${tx.map(t=>`<div class="timeline-item"><strong>${esc(t.title)}</strong><p>${esc(t.name)} · ${money(t.amount)}</p><small>${t.time} · ${esc(tableName)} · INR</small></div>`).join('')}</div>${notice('Corrections retain the earlier entry, a reason and the table’s settings at that point in time.')}`}
function review(){const b=balance();return head('One final check','Every stack. Every chip.','table')+notice(b.pending.length?`${b.pending.length} players still need a cash-out.`:b.difference?'The table does not balance yet.':'All stacks balance.',b.pending.length||b.difference?'warn':'good')+`<section class="card">${detail('Player buy-ins',money(b.buy))}${detail('Cash-out stacks',money(b.out))}${detail('Rake',money(rakeTotal))}${detail('Difference',money(b.difference),'total')}</section><div class="section-head"><h2>Cash-out stacks</h2></div>${players.map(p=>`<div class="list-row">${identity(p,p.out===null?'Stack not entered':money(p.out))}${button(p.out===null?'Enter stack':'Edit','cashout','compact',`data-id="${p.id}"`)}</div>`).join('')}<div class="actions"><button class="button primary" data-action="close-table" ${b.pending.length||b.difference?'disabled':''}>Confirm table & settle</button>${link('Review activity','activity')}</div><p class="hint">A table can close only when all stacks, including zeroes, are entered and balance with rake.</p>`}
function historyCard(name,date,sub,tail){return `<a class="card" style="display:block;margin-top:12px" href="#history-detail"><div class="row"><span class="tag good">Balanced</span><small>${date}</small></div><h3 style="margin-top:12px">${name}</h3><p class="small" style="margin:6px 0 10px">${sub}</p><div class="row"><strong style="font-size:13px">${tail}</strong>${icon('arrow')}</div></a>`}
let historyKind='cash',insightSession=9;
const insightValues=[70,85,60,110,95,120,80,90,110,100];
const insightDates=['09 Oct','12 Oct','15 Oct','18 Oct','21 Oct','24 Oct','27 Oct','30 Oct','03 Nov','06 Nov'];
function historySelector(){return `<div class="history-selector" role="group" aria-label="History game type" style="--selected:${historyKind==='cash'?0:1}">${[['cash','table','Cash games',10],['tournament','cup','Tournaments',1]].map(([id,i,label,count])=>`<button data-action="history-kind" data-value="${id}" aria-pressed="${historyKind===id}">${icon(i)}<span>${label}</span><b>${count}</b></button>`).join('')}</div>`}
function historyContent(){return `<div class="archive-caption"><span>${historyKind==='cash'?'10 completed cash tables':'1 completed tournament'}</span><span>Latest first ${icon('history')}</span></div>`+(historyKind==='cash'?['Friday Regulars','Midweek Mix','After Hours','Sunday Session','Saturday Regulars','Friday Night','After Hours II','Sunday Session II','Midweek Mix II','Saturday Regulars II'].map((name,i)=>historyCard(name,`${6-i*3>0?6-i*3:30-i} ${i<2?'Nov':'Oct'} 2026`,'9 players · ₹90,000 buy-ins',i===0?'₹6,200 outstanding':'All payments recorded')).join(''):`<a class="tournament-archive card" href="#tournament-results"><div class="archive-cup">${icon('cup')}</div><div><span class="eyebrow">SINGLE TABLE · 06 NOV 2026</span><h2>Friday Cup</h2><p>9 entries · ₹15,000 prize pool</p><strong>Jamie Chen · 1st place</strong></div>${icon('arrow')}</a>`)}
function historyPage(){return head('Nights worth keeping.','Your tables, results and the last few things to settle.','home')+historySelector()+`<div id="history-results">${historyContent()}</div>`}

function historyDetail(){return head('Friday Regulars','6 Nov 2026 · completed cash table','history')+notice('All 9 stacks entered. Buy-ins = cash-outs + rake.','good')+`<section class="card">${detail('Buy-ins','₹90,000')}${detail('Cash-outs','₹88,200')}${detail('Rake','₹1,800')}</section><div class="section-head"><h2>Final results</h2></div>${[['Jamie Chen','+₹2,200'],['Alex Morgan','−₹2,000'],['Sam Rivera','−₹2,000'],['Jordan Patel','−₹5,000']].map(([n,v])=>`<div class="list-row"><div class="grow"><strong>${n}</strong></div><strong class="${v[0]==='+'?'positive':'negative'}">${v}</strong></div>`).join('')}<p class="small">4 of 9 players shown</p><div class="actions">${link('Results & settlement','settlement','primary')}${link('Player receipts','receipt')}${button('Export transaction CSV','export-csv')}</div>`}
function trend(){return `<section class="card" style="margin:16px 0"><div class="row"><h3>Cumulative result</h3><small>10 sessions</small></div><svg class="chart" viewBox="0 0 350 125" role="img" aria-label="Cumulative result over ten sessions, ending at positive 12,400 rupees"><path class="grid" d="M0 100H350M0 55H350"/><path class="line" d="M0 110 35 80 70 99 105 48 140 83 175 59 210 42 245 69 280 29 315 52 350 31"/></svg><div class="row"><small>First session</small><small>Latest</small></div></section>`}
function insightPlayerCard(){const net=profileSessions.reduce((total,s)=>total+s.net,0),wins=profileSessions.filter(s=>s.net>0).length;let running=0;const points=profileSessions.map((s,i)=>`${i*22},${55-(running+=s.net)/14000*48}`).join(' ');return `<button class="insight-player-card" data-action="profile" data-id="2"><div class="insight-player-top">${avatar(contacts[1])}<div><span class="eyebrow">PLAYER SPOTLIGHT</span><h3>Jamie Chen</h3><small>10 completed cash sessions</small></div><span class="card-arrow">${icon('arrow')}</span></div><div class="insight-player-result"><div><small>Net poker result</small><strong class="positive">${signed(net)}</strong></div><svg viewBox="0 0 200 65" aria-hidden="true"><path d="M0 60H200" stroke="var(--line)"/><polyline points="${points}" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linejoin="round"/></svg></div><div class="insight-player-bottom"><span><b>${wins} / 10</b> winning sessions</span><span>Open player profile ${icon('arrow')}</span></div></button>`}
function insightChart(){return `<section class="card insight-chart" id="insight-chart" aria-label="Session buy-ins"><div class="row"><div><span class="eyebrow">THE SHAPE OF YOUR NIGHTS</span><h2>Session buy-ins</h2></div><span class="chart-unit">INR</span></div><div class="chart-readout" aria-live="polite"><div><strong id="insight-value">${money(insightValues[insightSession]*1000)}</strong><small id="insight-date">${insightDates[insightSession]} 2026 · session ${insightSession+1} of 10</small></div><span>Includes rebuys</span></div><div class="insight-bars" role="group" aria-label="Inspect session buy-ins">${insightValues.map((v,i)=>`<button style="--height:${v/120*100}%" data-action="insight-session" data-value="${i}" aria-label="${insightDates[i]}, ${money(v*1000)} buy-ins" aria-pressed="${insightSession===i}"><span></span><small>${i+1}</small></button>`).join('')}</div><div class="chart-axis"><span>09 Oct</span><span>06 Nov 2026</span></div><label class="sr-only" for="insight-slider">Inspect session buy-ins</label><input id="insight-slider" class="session-slider" type="range" min="0" max="9" step="1" value="${insightSession}" aria-valuetext="${insightDates[insightSession]}, ${money(insightValues[insightSession]*1000)} buy-ins"><details class="source-disclosure"><summary><span class="source-icon">${icon('receipt')}</span><span><strong>Behind the chart</strong><small>10 sessions · exact source values</small></span><span class="disclosure-chevron">${icon('back')}</span></summary><div class="source-body"><table><caption>Completed cash tables · INR</caption><thead><tr><th scope="col">Session</th><th scope="col">Buy-ins</th></tr></thead><tbody>${insightValues.map((v,i)=>`<tr><td><span class="source-index">${String(i+1).padStart(2,'0')}</span>${insightDates[i]} 2026</td><td>${money(v*1000)}</td></tr>`).join('')}</tbody><tfoot><tr><th scope="row">Total · 10 sessions</th><td>${money(insightValues.reduce((a,b)=>a+b,0)*1000)}</td></tr></tfoot></table><p>Initial buy-ins + rebuys. Cash games only.</p></div></details></section>`}
function insights(){return head('The nights add up.','A clearer picture of the games you keep.','home')+`<div class="insight-overview"><span class="eyebrow">10 TABLES · 15 PLAYERS</span><h2>Good company.<br>A story in every session.</h2><img src="assets/table-sculpture.svg" alt="Illustrated green poker table"><div class="insight-overview-total"><small>Total table buy-ins</small><strong>₹9,20,000</strong><span>Across 10 completed cash sessions</span></div></div><div class="insight-metrics"><div>${icon('clock')}<small>Average play time</small><strong>4h 20m</strong><span>8 of 10 sessions timed</span></div><div>${icon('table')}<small>Total rake</small><strong>₹18,400</strong><span>10 completed tables</span></div></div>`+insightChart()+`<p class="data-footnote">${icon('shield')}<span>Completed sessions only. Missing play times are excluded. Tournament results stay separate.</span></p><div class="section-head"><div><span class="eyebrow">THE PEOPLE AT YOUR TABLE</span><h2>Player insights</h2></div>${link('All players','players','text')}</div>`+insightPlayerCard()+`<div class="data-tools"><div>${icon('receipt')}<strong>Your data, your perspective.</strong><small>CSV insights are planned for phase two.</small></div><div>${button('Import CSV','csv-import')}${button('Export source data','export-csv')}</div></div>`}

function settlement(){return head('Table settlement','Friday Regulars · balanced stacks','history-detail')+hero('Player payments remaining',money(activeTransferAmount),`<small>${transferPaid?'All player payments recorded':'1 transfer · recorded payments excluded'}</small>`)+`<div class="segment" aria-label="Settlement method"><button class="selected" data-action="bank-mode" aria-pressed="true">Through banker</button><button data-action="direct-mode" aria-pressed="false">Smart direct</button></div>${transferPaid?notice('All player payments recorded.','good'):`<section class="card"><div class="row"><strong>Banker → Jamie Chen</strong><span class="tag warn">Unpaid</span></div><div class="amount medium">${money(activeTransferAmount)}</div>${link('Record paid','payment','primary w-full')}</section>`}<div class="list-row"><div class="grow"><strong>Rake · ₹1,800</strong><small>Distributed outside the app</small></div></div><div class="actions">${link('Recorded payments & corrections','payments')}${link('Player receipts','receipt')}${button('Share table summary','share-summary')}</div><p class="hint">Record payments after money changes hands. The app does not transfer money.</p>`}
function payment(){return head('Record payment','Banker → Jamie Chen','settlement')+hero('Amount remaining',money(activeTransferAmount))+`<form data-form="payment"><div class="field"><label for="payment-amount">Amount paid · ₹</label><input id="payment-amount" inputmode="decimal" value="${activeTransferAmount}" required></div>${notice('Confirm only after the money has changed hands. Partial payments leave the rest outstanding.')}<label class="check"><input type="checkbox" required> I confirm this money was paid.</label><div class="actions"><button class="button primary" type="submit">Confirm payment recorded</button></div></form>`}
function paymentsPage(){return head('Recorded payments','Corrections stay in the history.','settlement')+`<div class="list-row"><div class="grow"><strong>Banker → Jamie Chen</strong><small>₹5,000 · 6 Nov, 22:15</small></div><span class="tag good">Recorded</span></div>${transferPaid?'<div class="list-row"><div class="grow"><strong>Banker → Jamie Chen</strong><small>₹6,200 · 6 Nov, 23:18</small></div><span class="tag good">Recorded</span></div>':''}${notice('Reverse a record only if it was entered incorrectly. Reversal does not move money back.')}<form data-form="reverse"><div class="field"><label for="reverse-reason">Reason to reverse the ₹5,000 record</label><input id="reverse-reason" minlength="3" maxlength="160" required placeholder="Marked paid by mistake"></div><div class="actions"><button class="button danger" type="submit">Review record reversal</button></div></form>`}
function receiptModel(current=false){
 const p=current?(players.find(p=>p.id===currentReceiptPlayerId)||players[0]):receiptPlayers[receiptId];
 if(!p)return null;
 let entries=p.entries;
 if(current){entries=tx.filter(t=>t.name===p.name&&/buy-in|rebuy/i.test(t.title)&&!t.title.includes('corrected')).map(t=>[t.time+' · '+t.title,t.amount]).reverse();if(!entries.length)entries=[['Initial buy-in',p.buy]];const difference=p.buy-entries.reduce((n,e)=>n+e[1],0);if(difference)entries.push(['Correction adjustment',difference]);}
 const due=p.buy-(p.received||0)-(p.out||0)+(p.paid||0),banker=current?tableBanker.name:'Not recorded',party=banker&&banker!=='Not recorded'?banker:'Banker',selfBanker=current&&String(p.id)===tableBanker.id;
 return {banker,needsBanker:current&&!banker,name:p.name,table:current?tableName:'Friday Regulars',date:current?'Current table':'6 Nov 2026',entries,buy:p.buy,out:p.out,received:p.received||0,paid:p.paid||0,result:p.out===null?null:p.out-p.buy,due,label:p.out===null?'PROVISIONAL BALANCE':selfBanker?'BANKER BALANCE':due>0?'STILL TO PAY':due<0?'STILL TO RECEIVE':'SETTLED',direction:selfBanker?'Banker’s own entry · no self-transfer':due>0?p.name+' → '+party:due<0?party+' → '+p.name:'No payment outstanding',reference:current?'Current table snapshot':'Receipt C-013 · revision 4'};
}
function receiptDocument(m){if(!m)return '';const row=(label,value,cls='')=>`<div class="receipt-row ${cls}"><span>${esc(label)}</span><b>${esc(value)}</b></div>`;return `<section class="receipt" aria-label="Receipt for ${esc(m.name)}"><img class="receipt-logo" src="../../wireframes/assets/brand/cash-out-wordmark-light.svg" alt="Cash Out"><div class="receipt-kicker">PLAYER RECEIPT · INR</div><div class="receipt-rule"></div><strong class="receipt-name">${esc(m.name)}</strong><div class="receipt-muted">${esc(m.table)} · ${esc(m.date)}<br>Cash game · Banker: ${esc(m.banker||'Name not set')}</div><div class="receipt-rule"></div>${m.entries.map(([label,n])=>row(label,n<0?signed(n):money(n))).join('')}<div class="receipt-rule"></div>${row('Total buy-ins',money(m.buy))}${row('Cash-out stack',m.out===null?'Not entered':money(m.out))}${row('Poker result',m.result===null?'Playing':signed(m.result),'receipt-result')}<div class="receipt-rule"></div>${row('Buy-ins received',money(m.received))}${row('Payout recorded',money(m.paid))}<div class="receipt-total ${m.due>0?'owed':m.due===0?'settled':''}"><div class="receipt-kicker">${m.label}</div><strong>${money(Math.abs(m.due))}</strong><div class="receipt-muted">${esc(m.direction)}</div>${m.out===null?'<small>Final balance follows cash-out.</small>':''}</div><div class="receipt-rule"></div><div class="receipt-foot">${esc(m.reference)}<br>Design preview · sample data<br>Record only · no money transferred</div></section>`}
function receipt(){return head('Player receipt','Friday Regulars · 6 Nov 2026',receiptBack)+`<label for="receipt-player">Player</label><select id="receipt-player">${Object.entries(receiptPlayers).map(([id,p])=>`<option value="${id}" ${id===receiptId?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`+receiptDocument(receiptModel())+receiptActions()+`<p class="hint">One player. No phone numbers, photos or other players’ results.</p>`}

function preferenceRow(title,description,i,route,action='',tail=''){return `<${action?'button':'a'} class="preference-row" ${action?`type="button" data-action="${action}"`:`href="#${route}"`}><span class="preference-icon">${icon(i)}</span><span class="preference-copy"><strong>${title}</strong><small>${description}</small></span>${tail?`<span class="preference-tag">${tail}</span>`:''}<span class="preference-arrow">${icon('arrow')}</span></${action?'button':'a'}>`}
function settings(){return head('Make yourself at home.','Your preferences. Your records. Your peace of mind.','home')+`<section class="appearance-panel"><span class="preference-icon">${icon('settings')}</span><div><strong>Dark appearance</strong><small>A comfortable view for long nights.</small></div><button class="toggle" data-action="theme" role="switch" aria-checked="${document.documentElement.dataset.theme==='dark'}" aria-label="Dark appearance"></button></section><div class="section-head"><div><span class="eyebrow">LOOK AFTER YOUR NIGHTS</span><h2>Save & recovery</h2></div></div><section class="recovery-feature"><div><span class="status-label"><i></i>ON THIS DEVICE</span><h2>Saved here.<br>Safer in two places.</h2><p>Your records are local. Connect a cloud backup for another copy.</p><a class="button primary" href="#cloud">Set up cloud backup ${icon('arrow')}</a></div><img src="assets/receipt-cloud.svg" alt="Receipt protected by a cloud and check mark"><div class="recovery-status"><span>${icon('check')} Local copy <strong>Saved on device</strong></span><span>${icon('shield')} Cloud copy <strong>Not connected</strong></span></div></section><div class="preference-group">${preferenceRow('Export full backup','Everything, including history and photos.','download','','export-backup')}${preferenceRow('Restore from a backup','Review the file before replacing records.','history','restore')}${preferenceRow('Export transaction CSV','A spreadsheet for analysis. Not a full backup.','receipt','','export-csv')}</div><p class="data-footnote">${icon('shield')}<span>Keep an independent copy. Clearing browser data can remove local records.</span></p><div class="section-head"><div><span class="eyebrow">READY FOR GAME NIGHT</span><h2>App & privacy</h2></div></div><div class="preference-group">${preferenceRow('Install Cash Out','A place on your home screen.','plus','install')}${preferenceRow('Privacy & recovery','What stays private, and how to recover.','shield','privacy')}</div>`}

function cloud(){return head('A safe place for every night.','Save & recovery','settings')+`<div class="illustrated-note"><img src="assets/receipt-cloud.svg" alt="Illustrated record and cloud"><div><h3>Saved here. Backed up elsewhere.</h3><p>Device saves and independent cloud copies have different jobs. Keep both statuses visible.</p></div></div>`+`<section class="card">${detail('Provider','Google Drive')}${detail('Connection','Not connected')}${detail('Last cloud backup','Not yet')}</section>${notice('Cash Out requests access only to its own hidden app-data folder, not the rest of your Drive.')}<div class="actions">${button('Connect Google Drive','connect-google','primary')}</div><div class="section-head"><h2>iCloud Drive</h2></div><p class="small">Export a full backup, then save it to iCloud Drive through Files. Automatic iCloud backup is not connected.</p><div class="actions">${button('Export full backup','export-backup')}</div>${notice('CSV is for analysis. A full backup is needed to restore players, photos, tables, payments and activity.')}`}
function restore(){return head('Restore full backup','Preview before replacing your records.','settings')+`<form data-form="restore"><div class="field"><label for="restore-file">Cash Out backup · JSON</label><input id="restore-file" type="file" accept="application/json,.json" required></div>${notice('The file is checked before restoration. Current records stay untouched until you confirm replacement.')}<div class="actions"><button class="button primary" type="submit">Check backup file</button></div></form>`}
function restoreReview(){return head('Restore this backup?','Check the contents before continuing.','restore')+`<section class="card">${detail('Backup date','12 Nov 2026, 23:18 IST')}${detail('Players','15')}${detail('Completed tables','10')}${detail('Current table','Friday Night')}${detail('Audit entries','186')}${detail('Photos and payments','Included')}</section>${notice('This replaces the records on this device. Export a full backup of the current workspace first.','warn')}<form data-form="restore-confirm"><label class="check"><input type="checkbox" required> I have kept a backup of my current records.</label><div class="actions"><button class="button primary" type="submit">Restore backup</button>${link('Keep current records','settings')}</div></form>`}
function install(){return head('Install Cash Out','Keep the app within reach.','settings')+`<section class="card"><h2>iPhone / iPad</h2><div class="timeline" style="margin-top:20px">${['Open Cash Out in Safari.','Open Share, then Add to Home Screen.','Confirm the name, then tap Add.'].map((t,i)=>`<div class="timeline-item"><strong>${i+1}.</strong> ${t}</div>`).join('')}</div></section><section class="card" style="margin-top:16px"><h2>Android</h2><p class="small" style="margin-top:12px">Open the browser menu, then choose Install app or Add to Home screen.</p></section>${notice('Open online once to prepare offline files. Installation is separate from backing up your data.')}<div class="actions">${button('Check offline readiness','check-offline')}</div>`}
function privacy(){return head('Privacy & recovery','You control what leaves your device.','settings')+`<div class="stack"><section class="card"><h3>Private records</h3><p class="small" style="margin-top:10px">Player contact details, photos and table records stay private. Shared receipts contain only the selected player’s results and relevant payments.</p></section><section class="card"><h3>Device storage</h3><p class="small" style="margin-top:10px">Clearing site data or losing this device can remove local records. Keep a full backup somewhere independent.</p></section><section class="card"><h3>Files and cloud</h3><p class="small" style="margin-top:10px">Full backups and CSV exports contain private information. Store and share them carefully. A downloaded file is not a confirmed recoverable backup until you check it.</p></section></div><div class="actions">${link('Backup settings','cloud','primary')}${button('Check storage protection','protect-storage')}</div>`}
let tournamentRunning=false,tournamentDeadline=0,tournamentSeconds=1122,tournamentLevel=4,tournamentEliminated=false,tournamentStarted=false,tournamentBreak=false;
function tournamentTabs(selected){return `<nav class="segment" aria-label="Tournament pages">${[['tournament-setup','Setup'],['tournament','Live'],['tournament-payouts','Payouts']].map(([r,l])=>`<a href="#${r}" class="${selected===r?'selected':''}" ${selected===r?'aria-current="page"':''}>${l}</a>`).join('')}</nav>`}
function tournamentSetup(){return head('Start tournament','One table. Clear rules from the first hand.','home')+`<form data-form="tournament-setup"><div class="field"><label for="tournament-name">Tournament name</label><input id="tournament-name" value="Friday Cup" maxlength="60" required></div><div class="two"><div class="field"><label for="starting-stack">Starting chips</label><input id="starting-stack" type="number" min="1" value="20000" required></div><div class="field"><label for="tournament-buy">Entry · ₹</label><input id="tournament-buy" inputmode="decimal" value="1500" required></div></div><div class="two"><div class="field"><label for="level-length">Level · minutes</label><input id="level-length" type="number" min="1" value="20" required></div><div class="field"><label for="seats">Seats</label><input id="seats" type="number" min="2" max="10" value="9" required></div></div><div class="field"><label for="registration-level">Registration closes after</label><select id="registration-level"><option>Level 4</option><option>Level 3</option><option>Before play starts</option></select></div><div class="list-row"><div class="grow"><strong>Rebuys</strong><small>₹1,000 · until level 4 ends</small></div><input type="checkbox" aria-label="Allow rebuys" checked></div><div class="list-row"><div class="grow"><strong>Add-on</strong><small>₹500 · one per player</small></div><input type="checkbox" aria-label="Allow add-on" checked></div>${link('Review blind & break structure','tournament-structure','text w-full')}${notice('Tournament chips have no cash exchange value. Entry money, fees, prizes and actual payments are recorded separately.')}<div class="actions"><button class="button primary" type="submit">Review tournament</button></div></form>`}
function structure(){return head('Blind structure','20-minute levels · big blind ante','tournament-setup')+`<section class="card">${[['1','25 / 50','—'],['2','50 / 100','100'],['3','75 / 150','150'],['4','100 / 200','200'],['Break','10 minutes',''],['5','150 / 300','300'],['6','200 / 400','400'],['7','300 / 600','600']].map(([l,b,a])=>detail(l==='Break'?'Break':'Level '+l,`${b}${a?' · ante '+a:''}`)).join('')}</section>${notice('Late registration and rebuys close after level 4. Review all levels, break times and the heads-up ante policy before starting.')}<div class="actions">${link('Back to setup','tournament-setup','primary')}</div>`}
function tournament(){const seconds=tournamentRunning?Math.max(0,Math.ceil((tournamentDeadline-Date.now())/1000)):tournamentSeconds;const blind=blindAtLevel(tournamentLevel),next=blindAtLevel(Math.min(7,tournamentLevel+1));return head(esc(tournamentConfig.name),'One table · '+tournamentConfig.seats+' players','home')+tournamentTabs('tournament')+`<div class="tournament-banner"><div><span class="tag">One table · tournament</span><h2>A night for the title.</h2><p>Every level. Every finish. Every prize.</p></div><img src="assets/trophy.svg" alt="Illustrated gold tournament trophy"></div>`+`<section class="clock-panel"><span class="eyebrow" id="level-label">${tournamentBreak?'Break':'Level '+tournamentLevel} · ${tournamentRunning?'running':'paused'}</span><div class="clock-number" id="tournament-clock">${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}</div><strong style="font-size:24px">${tournamentBreak?'10-minute break':blind.small+' / '+blind.big} <small>chips</small></strong><p class="small">Big blind ante · ${tournamentBreak?'—':blind.ante} chips</p><div class="context-rule"></div><small>Next: ${tournamentLevel===4&&!tournamentBreak?'Break · 10 minutes, then 150 / 300':next.small+' / '+next.big+' · '+next.ante+' ante'}</small></section><div class="two" style="margin-top:14px">${button(tournamentRunning?'Pause clock':'Resume clock','tournament-pause')}${button(tournamentBreak?'End break':tournamentLevel===4?'Take break':'Next level','tournament-next')}</div><div class="section-head"><h2>${tournamentEliminated?'6':'7'} remaining</h2>${link('Entrants & seats','tournament-players','text compact')}</div><section class="card">${detail('Prize pool','₹15,000')}${detail('Paid places','3')}${detail('Registration','Open until level 4 ends')}</section><div class="actions">${link('Add entry / rebuy','tournament-entry')}${link('Record elimination','tournament-elimination')}${link('Review prizes','tournament-payouts')}</div>`}
function tournamentPlayers(){return head('Entrants & seats','Friday Cup · 9 players','tournament')+contacts.slice(0,9).map((p,i)=>`<div class="list-row"><span class="tag">${i+1}</span>${identity(p,i===2&&tournamentEliminated?'Finished 7th':i>6?'Eliminated':'Playing')}<span class="small ${i>6?'muted':'positive'}">${i>6?'Out':'Entry paid'}</span></div>`).join('')+`<div class="actions">${link('Add entry / rebuy','tournament-entry','primary')}</div>`}
function tournamentEntry(){return head('Tournament entry','Cash and chips are separate.','tournament')+`<form data-form="tournament-entry"><div class="field"><label for="entrant">Player</label><select id="entrant">${contacts.slice(0,9).map(p=>`<option>${p.name}</option>`).join('')}</select></div><div class="field"><label for="entry-type">Entry type</label><select id="entry-type"><option value="rebuy">Rebuy · ₹1,000 · 20,000 chips</option><option value="initial">Initial entry · ₹1,500 · 20,000 chips</option><option value="addon">Add-on · ₹500 · 10,000 chips</option></select></div>${notice('Allowed until level 4 ends. A rebuy/add-on changes the prize pool and is retained in the tournament ledger.')}<fieldset class="field"><legend>Entry payment</legend><label class="check"><input type="radio" name="entry-received" value="yes" required> Received now</label><label class="check"><input type="radio" name="entry-received" value="no"> Not yet · track as due</label></fieldset><div class="actions"><button class="button primary" type="submit">Review entry</button></div></form>`}
function elimination(){return head('Record elimination','Finish order stays traceable.','tournament')+`<form data-form="elimination"><div class="field"><label for="eliminated-player">Player</label><select id="eliminated-player">${contacts.slice(0,7).map(p=>`<option ${p.id===3?'selected':''}>${p.name}</option>`).join('')}</select></div><section class="card" style="margin-top:20px">${detail('Finish position','7th')}${detail('Prize','₹0')}${detail('Players remaining after','6')}</section>${notice('Check simultaneous eliminations and finish order before confirming. Recording a place never marks a prize as paid.')}<label class="check"><input type="checkbox" required> I checked the player and finishing position.</label><div class="actions"><button class="button primary" type="submit">Confirm elimination</button>${link('Keep player in','tournament')}</div></form>`}
function prizePool(){return head('Prize pool & payouts','Friday Cup','tournament')+tournamentTabs('tournament-payouts')+hero('Cash prize pool','₹15,000')+`<section class="card" style="margin-top:16px">${detail('9 entries × ₹1,500','₹13,500')}${detail('2 rebuys × ₹1,000','₹2,000')}${detail('1 add-on × ₹500','₹500')}${detail('Disclosed fees','−₹1,000')}</section><div class="section-head"><h2>Payout structure</h2><span class="tag good">100%</span></div><section class="card">${detail('1st · 50%','₹7,500')}${detail('2nd · 30%','₹4,500')}${detail('3rd · 20%','₹3,000')}${detail('Total','₹15,000','total')}</section>${notice('Entries and prizes must reconcile exactly. Unpaid entries remain visible; promised contributions are not money held.')}<div class="actions">${link('Final standings','tournament-results','primary')}${button('Edit payout structure','edit-prizes')}</div>`}
function tournamentResults(){return head('Final standings','Friday Cup · completed tournament','history')+hero('Prize pool','₹15,000')+`<div class="section-head"><h2>Paid places</h2></div>${[['1','Jamie Chen','₹7,500'],['2','Alex Morgan','₹4,500'],['3','Taylor Reed','₹3,000']].map(([rank,name,prize])=>`<section class="card" style="margin-top:10px"><div class="row"><div><span class="tag">${rank}${rank==='1'?'st':rank==='2'?'nd':'rd'}</span><h3 style="margin-top:10px">${name}</h3></div><strong>${prize}</strong></div><small>Prize not recorded paid</small></section>`).join('')}<div class="actions">${button('Review prize payments','tournament-prize-payment','primary')}${button('Share results','share-tournament')}</div>${notice('A finishing position and a paid prize are separate records. Cash-game call-time rules do not apply to tournament elimination.')}`}
function components(){return `<section class="component-section"><span class="eyebrow">REFINED DATA & NAVIGATION</span>${historySelector()}${insightPlayerCard()}${insightChart()}<div class="preference-group">${preferenceRow('Export full backup','History, photos and records.','download','','export-backup')}</div></section>`+head('One system. Every screen.','Reusable components, illustrations and interaction states.','home')+`<section class="component-section"><span class="eyebrow">NEW DIRECTIONS · SHARED COMPONENTS</span>${homeActionTiles()}<div class="two"><div class="card"><img src="assets/table-sculpture.svg" alt="Poker table illustration" style="width:100%;height:auto"><p class="small">Home · good company, clear numbers.</p></div><div class="card"><img src="assets/trophy.svg" alt="Tournament illustration" style="width:100%;height:auto"><p class="small">Tournament · a little ceremony.</p></div></div></section>`+`<section class="component-section"><span class="eyebrow">01 / Identity & surfaces</span><div class="profile-result magic-card" style="margin-top:14px"><span class="eyebrow">Net poker result</span><div class="amount positive">+₹12,400</div><p class="small">Magic UI surface · exact values stay still</p></div>${identity(contacts[1],'Saved player · stable identity')}</section><section class="component-section"><span class="eyebrow">02 / Statistics</span><div class="two stats-grid" style="margin-top:14px">${statCard('Average win','+₹4,800','6 winning sessions','positive')}${statCard('Average loss','−₹4,100','4 losing sessions','negative')}</div></section><section class="component-section"><span class="eyebrow">03 / Navigation & data</span>${profileTabs('Component profile tabs')}${profileTab==='overview'?profileTrend():profileSessionRows()}</section><section class="component-section"><span class="eyebrow">04 / Financial controls</span><div class="stack" style="margin-top:14px">${link('Primary action','home','primary')}${link('Secondary action','home')}${link('Destructive review','early-exit','danger')}<button class="button" disabled>Unavailable action</button></div><div class="player-grid">${players.map(playerCard).join('')}</div></section><section class="component-section"><span class="eyebrow">05 / Feedback & recovery</span>${notice('Saved on this device. Cloud backup is a separate status.','good')}${notice('Check the amount before recording.','warn')}${notice('Unable to save. Keep your entry open.','error')}<button class="button primary w-full" data-action="component-save">Update preference</button><p class="small" style="margin-top:10px">Spectrum action feedback follows completion. Exact money and touch targets do not morph.</p></section><section class="component-section"><span class="eyebrow">06 / Receipts & dialogs</span><div class="stack" style="margin-top:14px">${link('Player receipt · receive / pay / settled','receipt')}${link('Early profitable exit warning','early-exit')}${link('Table settings','table-settings')}</div></section>`}
const pages={home,'new-table':newTable,table,'table-settings':tableSettings,players:()=>roster(false),'add-player':()=>roster(true),'new-player':playerForm,player:profile,'buy-in':amountPage,'amount-review':amountReview,'cash-out':cashout,'cash-out-review':()=>cashReview(false),'early-exit':()=>cashReview(true),correction:()=>{amountDraft.kind='correction';if(!players.some(p=>p.id===amountDraft.id))amountDraft.id=players[0].id;if(!amountDraft.amount)amountDraft.amount=String(players[0].buy);return amountPage()},review,activity,history:historyPage,'history-detail':historyDetail,insights,settlement,payment,payments:paymentsPage,receipt,'current-receipt':currentReceipt,settings,cloud,restore,'restore-review':restoreReview,install,privacy,'tournament-setup':tournamentSetup,'tournament-review':tournamentRuleReview,'tournament-structure':structure,tournament,'tournament-players':tournamentPlayers,'tournament-entry':tournamentEntry,'tournament-elimination':elimination,'tournament-payouts':prizePool,'tournament-results':tournamentResults,components,'rake-entry':rakeEntry,'rake-review':rakeReview,'share-preview':sharePreview,'csv-import':csvImport,'save-pending':()=>saveState('pending'),'save-error':()=>saveState('error'),'save-success':()=>saveState('success'),'empty-table':emptyTableDesign};
function updateNavigation(markup,selected){
 const root=$('#navigation');
 if(!root.querySelector('.nav')){root.innerHTML=markup;return}
 root.querySelectorAll('.nav a').forEach(a=>{const active=a.getAttribute('href')==='#'+selected;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
}
function render(){activeInfo=false;$('#toast').textContent='';currentRoute=location.hash.slice(1)||'home';if(!pages[currentRoute])currentRoute='home';if(currentRoute==='early-exit'&&cashDraft.amount==='')cashDraft.amount='7000';const meta=routeMeta.find(r=>r.id===currentRoute);$('.device').dataset.route=currentRoute;$('.device-status').innerHTML=`<span></span>${currentRoute==='save-pending'?'Saving entry…':currentRoute==='save-error'?'Entry not saved':'Device saved'}<small>Cloud not connected</small>`;$('#screen').innerHTML=pages[currentRoute]();if(currentRoute==='early-exit'&&$('#early-exit-dialog')?.showModal){$('#early-exit-dialog').showModal();$('#early-exit-dialog').addEventListener('cancel',e=>{e.preventDefault();go('cash-out')})}$('#screen-name').textContent=meta?.label||'Home';$('#screen-context').textContent=contexts[currentRoute]||'A production-facing screen with the same components, navigation and confirmation rules as the rest of Cash Out.';$('#routes').innerHTML=Object.entries(groups).map(([group,rs])=>`<div class="map-group">${group}</div>${rs.map(([r,l])=>`<a href="#${r}" class="map-link ${r===currentRoute?'current':''}" ${r===currentRoute?'aria-current="page"':''}>${l}</a>`).join('')}`).join('');$('#page-count').textContent=routeMeta.length;const selected=currentRoute.startsWith('tournament')||['home','new-table','table','table-settings','add-player','buy-in','amount-review','cash-out','cash-out-review','early-exit','correction','review','activity','settlement','payment','payments','receipt'].includes(currentRoute)?'home':['players','player','new-player'].includes(currentRoute)?'players':currentRoute.startsWith('history')?'history':currentRoute==='insights'?'insights':'';updateNavigation(`<a class="rail-brand" href="#home" aria-label="Cash Out home"><img class="dark-logo" src="../../wireframes/assets/brand/cash-out-wordmark-dark.svg" alt="Cash Out"><img class="light-logo" src="../../wireframes/assets/brand/cash-out-wordmark-light.svg" alt="Cash Out"></a><span class="rail-label">YOUR GAME NIGHT</span><div class="nav">${[['home','table','Tables'],['players','players','Players'],['history','history','History'],['insights','chart','Insights']].map(([r,i,l])=>`<a href="#${r}" class="${r===selected?'active':''}" ${r===selected?'aria-current="page"':''}>${icon(i)}${l}</a>`).join('')}</div><div class="rail-bottom">Private by default.<br>Careful with every chip.<a href="#cloud">Save & recovery ↗</a><a href="#components">Component library ↗</a></div>`,selected);$('#settings-link').innerHTML=icon('settings');window.CashMotionLibrary?.mount($('#screen'));$('#page-map').classList.remove('open');$('#map-control').setAttribute('aria-expanded','false')}
function theme(){const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';$('#theme-control').textContent=dark?'Light theme':'Dark theme';$('#theme-control').setAttribute('aria-label',dark?'Switch to light theme':'Switch to dark theme');if(currentRoute==='settings')render()}
function amountValue(value){return /^\d{1,9}(?:\.\d{0,2})?$/.test(value)&&Number.isFinite(Number(value))?Number(value):null}
