let activeTransferAmount=6200;
document.addEventListener('click',async e=>{const anchor=e.target.closest('a[href^="#"]');if(activeInfo&&anchor?.getAttribute('href')===location.hash){e.preventDefault();render();return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=Number(b.dataset.id);switch(a){
case'theme':theme();break;case'profile-tab':profileTab=b.dataset.value;render();document.querySelector('.profile-segment .selected')?.focus({preventScroll:true});break;case'filter':filter=b.dataset.value;render();document.querySelector(`[data-action="filter"][data-value="${filter}"]`)?.focus({preventScroll:true});break;
case'profile':profileId=id;go('player');break;case'edit-player':editPlayerId=id;go('new-player');break;
case'seat':if(players.some(p=>p.id===id)){toast('Already seated at this table.');break}amountDraft={kind:'buy',id,amount:'',received:'',reason:''};go('buy-in');break;
case'rebuy':case'reentry':amountDraft={kind:a,id,amount:'',received:'',reason:''};go('buy-in');break;
case'cashout':cashDraft={id,amount:players.find(p=>p.id===id)?.out===null?'':String(players.find(p=>p.id===id)?.out||0),override:false};go('cash-out');break;
case'player-payments':go('payment');break;
case'player-options':amountDraft={kind:'correction',id,amount:String(players.find(p=>p.id===id)?.buy||0),received:'',reason:''};go('correction');break;
case'archive':if(!b.dataset.confirm){b.dataset.confirm='yes';b.textContent='Confirm archive · history kept'}else{contacts.find(p=>p.id===id).archived=true;go('players')}break;
case'shortcut':{const n=(Number($('#amount')?.value)||0)+Number(b.dataset.value);if($('#amount')){$('#amount').value=String(n);amountDraft.amount=String(n)}break}
case'clear':if($('#amount')){$('#amount').value='';amountDraft.amount=''}break;
case'key':{const input=$('#amount')||$('#cash-stack');if(!input)break;const v=b.dataset.value,next=v==='⌫'?input.value.slice(0,-1):input.value+v;if(/^\d{0,9}(?:\.\d{0,2})?$/.test(next)){input.value=next;input.dispatchEvent(new Event('input',{bubbles:true}))}break}
case'confirm-amount':{if(b.disabled)return;b.disabled=true;const n=Number(amountDraft.amount)||2000;let p=players.find(p=>p.id===amountDraft.id);if(!p){p={...contacts.find(p=>p.id===amountDraft.id),buy:0,out:null,received:0,firstBuy:Date.now(),minimum:minimumHours*3600000};players.push(p)}if(amountDraft.kind==='correction')p.buy=n;else{if(amountDraft.kind==='reentry'){p.priorOut=p.out||0;p.out=null}p.buy+=n;if(amountDraft.received==='yes')p.received+=n}p.last=n;tx.unshift({name:p.name,title:amountDraft.kind==='correction'?'Buy-in corrected':'Buy-in recorded',amount:n,time:'Now'});amountDraft.amount='';go('table');break}
case'allow-early':await window.CashMotionLibrary?.closeModal($('#early-exit-dialog'));cashDraft.override=true;go('cash-out-review');break;
case'confirm-cashout':{if(b.disabled)return;b.disabled=true;const p=person();p.out=(p.priorOut||0)+(Number(cashDraft.amount)||0);tx.unshift({name:p.name,title:cashDraft.override?'Cash-out · early-exit house exception':'Cash-out recorded',amount:p.out,time:'Now'});go('table');toast('Stack recorded · payout remains separate.',true);break}
case'close-table':if(!balance().pending.length&&balance().difference===0){tableClosed=true;go('settlement')}break;
case'rake':go('rake-entry');break;
case'bank-mode':case'direct-mode':{const seg=b.closest('.segment');seg.querySelectorAll('button').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});window.CashMotionLibrary?.moveSegment(seg);toast(a==='direct-mode'?'One outstanding recipient: the banker payout remains ₹6,200.':'Settlement routes through the banker.');break}
case'share-receipt':shareContext='receipt';go('share-preview');break;case'old-share-receipt':info('Share player receipt','Review the player’s receipt, then choose a person or destination in your device’s share sheet. No phone number or photo is included.','receipt');break;
case'save-receipt':window.print();break;
case'share-summary':shareContext='table';go('share-preview');break;case'old-share-summary':info('Share table summary','Friday Regulars · buy-ins ₹90,000 · cash-outs ₹88,200 · rake ₹1,800. Remaining: Banker → Jamie Chen ₹6,200. Names and amounts only.','settlement');break;
case'connect-google':info('Connect Google Drive','Continue with your Google account to back up Cash Out records to its own app-data folder. Live authorization will be available after the production app is configured.','cloud');break;
case'export-backup':case'export-csv':info(a==='export-backup'?'Export full backup':'Export transactions',a==='export-backup'?'Save the full backup to Files or your chosen drive. Check that the file exists before marking it as safely stored.':'The private CSV includes table details and auditable transactions. Share player receipts when you only want someone’s individual result.','settings');break;
case'check-offline':case'protect-storage':info('Device readiness','Offline files and storage protection must be checked on the installed app. Keep a separate full backup even when browser storage is protected.','install');break;
case'csv-import':go('csv-import');break;case'old-csv-import':info('Import transaction CSV','Choose a Cash Out CSV. Validate its schema, exact amounts and duplicate transaction IDs before generating insights. Existing ledger records remain unchanged.','insights');break;
case'tournament-pause':if(tournamentRunning){tournamentSeconds=Math.max(0,Math.ceil((tournamentDeadline-Date.now())/1000));tournamentRunning=false}else{tournamentDeadline=Date.now()+tournamentSeconds*1000;tournamentRunning=true}render();break;
case'tournament-next':if(!b.dataset.confirm){b.dataset.confirm='yes';b.textContent='Confirm advance';toast('Advance now? Remaining time will be discarded.')}else{tournamentRunning=false;if(tournamentLevel===4&&!tournamentBreak){tournamentBreak=true;tournamentSeconds=600}else{tournamentBreak=false;tournamentLevel=Math.min(7,tournamentLevel+1);tournamentSeconds=tournamentConfig.minutes*60}render()}break;
case'tournament-prize-payment':info('Review prize payments','Jamie Chen: ₹7,500 · Alex Morgan: ₹4,500 · Taylor Reed: ₹3,000. Record each prize as paid only after the money changes hands.','tournament-results');break;
case'edit-prizes':info('Edit payout structure','Three places: 50% / 30% / 20%. Total must be exactly 100%, with paise rounding allocated explicitly. Locked structures require an audited correction.','tournament-payouts');break;
case'share-tournament':shareContext='tournament';go('share-preview');break;case'old-share-tournament':info('Share tournament results','Friday Cup · 1st Jamie Chen ₹7,500 · 2nd Alex Morgan ₹4,500 · 3rd Taylor Reed ₹3,000. Payment status is shown separately.','tournament-results');break;
case'component-save':window.CashMotionLibrary?.runButton(b,async()=>undefined,{successLabel:'Preference updated'});break;case'component-danger':toast('Destructive actions require confirmation and preserve financial history.');break;
}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='session-inspector'){profileSession=Number(t.value);const holder=document.createElement('div');holder.innerHTML=profileTrend();const chart=t.closest('.profile-trend');chart.querySelector('.chart').outerHTML=holder.querySelector('.chart').outerHTML;chart.querySelector('#session-readout').innerHTML=holder.querySelector('#session-readout').innerHTML;t.setAttribute('aria-valuetext',holder.querySelector('#session-inspector').getAttribute('aria-valuetext'))}if(t.id==='player-search')$('#roster-results').innerHTML=rosterRows(t.value,currentRoute==='add-player');if(['amount','cash-stack','payment-amount'].includes(t.id)){const old=t.dataset.valid||'';if(!/^\d{0,9}(?:\.\d{0,2})?$/.test(t.value)){t.value=old;toast('Use numbers and up to two decimal places.')}else t.dataset.valid=t.value;if(t.id==='amount')amountDraft.amount=t.value;if(t.id==='cash-stack')cashDraft.amount=t.value}});
document.addEventListener('change',e=>{if(e.target.id==='banker'){const person=contacts.find(p=>String(p.id)===e.target.value);$('#banker-name').value=person?.name||(e.target.value===tableBanker.id?tableBanker.name:'');$('#banker-phone').value=person?.phone||(e.target.value===tableBanker.id?tableBanker.phone:'')}if(e.target.id==='receipt-player'){receiptId=e.target.value;render()}});
document.addEventListener('submit',e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();switch(form.dataset.form){
case'new-table':if(!tableClosed&&players.length){render();break}if(!readBanker())break;tableBanker=readBanker();tableClosed=false;rakeTotal=0;tx=[];tableName=$('#table-name').value.trim();minimumHours=Number($('#minimum-new').value);players=[];go('table');break;
case'table-settings':if(Number($('#big-blind').value)<Number($('#small-blind').value)){toast('Big blind must be at least the small blind.');break}if(!readBanker())break;tableBanker=readBanker();minimumHours=Number($('#minimum-hours').value);window.CashMotionLibrary?.runButton(form.querySelector('[type=submit]'),async()=>undefined,{successLabel:'Settings updated'});break;
case'player':{const name=$('#player-name').value.trim();if(!name)break;if(contacts.some(p=>p.id!==editPlayerId&&p.name.toLowerCase()===name.toLowerCase())){toast('A player with this name already exists. Check saved players.');break}if(editPlayerId){const p=contacts.find(p=>p.id===editPlayerId);Object.assign(p,{name,phone:$('#player-phone').value});const seated=players.find(p=>p.id===editPlayerId);if(seated)seated.name=name;editPlayerId=null}else contacts.push({id:Math.max(...contacts.map(p=>p.id))+1,name,phone:$('#player-phone').value,last:5000});go('players');break}
case'amount':{const n=amountValue($('#amount').value);if(n===null||n<=0){$('#amount-error').textContent='Enter an amount greater than zero using up to two decimal places.';break}amountDraft.amount=$('#amount').value;amountDraft.received=form.querySelector('[name=received]:checked')?.value||'';amountDraft.reason=$('#reason')?.value.trim()||'';go('amount-review');break}
case'cashout':{const n=amountValue($('#cash-stack').value);if(n===null){$('#cash-error').textContent='Enter a valid stack. Zero is allowed.';break}cashDraft.amount=$('#cash-stack').value;const p=person();go(n+(p.priorOut||0)>p.buy&&!clockFor(p).met?'early-exit':'cash-out-review');break}
case'payment':{const n=amountValue($('#payment-amount').value);if(n===null||n<=0||n>activeTransferAmount){toast('Enter a positive amount no greater than the remaining payment.');break}activeTransferAmount-=n;transferPaid=activeTransferAmount===0;receiptPlayers.jamie.paid+=n;go('settlement');toast('Payment recorded.',true);break}
case'reverse':info('Confirm record reversal','Reverse the ₹5,000 payment record? Reason: '+$('#reverse-reason').value.trim()+'. The original record stays in history; no money moves.','payments');break;
case'restore':if($('#restore-file').files.length)go('restore-review');break;
case'restore-confirm':restored=true;go('home');toast('Backup restored.');break;
case'tournament-setup':tournamentConfig={name:$('#tournament-name').value.trim(),chips:Number($('#starting-stack').value),entry:Number($('#tournament-buy').value),minutes:Number($('#level-length').value),seats:Number($('#seats').value),cutoff:$('#registration-level').value};go('tournament-review');break;
case'tournament-entry':info('Confirm tournament entry',$('#entrant').value+' · '+$('#entry-type').selectedOptions[0].text+'. Payment: '+(form.querySelector('[name=entry-received]:checked')?.value==='yes'?'received':'not yet received')+'. Review before recording.','tournament');break;
case'elimination':tournamentEliminated=true;go('tournament');toast('Finish position recorded. Prize payment stays separate.');break;
}});
$('#theme-control').onclick=theme;$('#map-control').onclick=()=>{const open=$('#page-map').classList.toggle('open');$('#map-control').setAttribute('aria-expanded',String(open))};
window.addEventListener('hashchange',()=>navigateDesign());
setInterval(()=>{document.querySelectorAll('[data-clock]').forEach(el=>{const p=players.find(p=>p.id===Number(el.dataset.clock));if(!p)return;const c=clockFor(p);el.classList.toggle('met',c.met);if(el.querySelector('strong').textContent!==(c.met?'✓':c.text))el.querySelector('strong').textContent=c.met?'✓':c.text;el.querySelector('small').textContent=c.met?'Eligible':'left'});if(currentRoute==='tournament'&&tournamentRunning){const sec=Math.max(0,Math.ceil((tournamentDeadline-Date.now())/1000));if($('#tournament-clock'))$('#tournament-clock').textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');if(sec===0){tournamentRunning=false;tournamentSeconds=0;render()}}},1000);
render();

/* New compositions share the established design-flow model; they do not load the app ledger. */
function home(){return `<section class="welcome"><div class="welcome-copy"><div class="eyebrow"><i></i> YOUR PEOPLE. YOUR TABLE.</div><h1>Good nights.<em>Clear numbers.</em></h1><p>From the first buy-in to the last payout.<br>A little less maths. A lot more poker.</p></div><figure class="welcome-art"><img src="assets/table-sculpture.svg" alt="Illustration of a green poker table, playing cards and stacked chips" width="600" height="430"><figcaption class="art-caption">GOOD COMPANY · CLEAR NUMBERS</figcaption></figure></section>${homeActionTiles()}<div class="home-columns"><div><div class="section-head"><h2>Still at the table</h2><span class="tag"><i class="live-dot"></i>Live</span></div><a class="live-table" href="#table"><span class="eyebrow">CASH GAME · TODAY</span><h2>${esc(tableName)}</h2><p>${players.length} players · ${balance().pending.length} still playing · You’re banking</p><div class="mini-avatars">${players.slice(0,4).map(avatar).join('')}<small>Good people. One private table.</small></div><div class="row"><div><small>Total buy-ins</small><div class="amount">${money(balance().buy)}</div></div><span class="button compact">Open table ${icon('arrow')}</span></div></a></div><div><div class="section-head"><h2>Recent nights</h2>${link('View all','history','text compact')}</div>${[['06','NOV','Friday Regulars','9 players · ₹6,200 outstanding'],['03','NOV','Midweek Mix','9 players · all settled'],['30','OCT','After Hours','9 players · all settled']].map(([d,m,n,s])=>`<a class="recent-item" href="#history-detail"><span class="recent-date">${d}<small>${m}</small></span><div><strong>${n}</strong><small>${s}</small></div>${icon('arrow')}</a>`).join('')}<a class="recent-item" href="#tournament"><span class="recent-date">${icon('cup')}</span><div><strong>Friday Cup</strong><small>Single table · level 4 paused</small></div>${icon('arrow')}</a></div></div><div class="home-footnote">${icon('shield')}<p>Your table is private. Share only what you choose.<br><a href="#cloud">Check your backup status ↗</a></p></div>`}
function playerDue(p){return p.buy-(p.received||0)-(p.out||0)+(p.paid||0)}
function playerCard(p){
 const c=clockFor(p),due=playerDue(p),playing=p.out===null,net=(p.out||0)-p.buy;
 const state=playing?'Playing':'Cashed out';
 const paymentLabel=due>0?'Buy-in unpaid':due<0?(playing?'Credit to return':'Payout due'):(playing?'Buy-in received':'Payments settled');
 return `<article class="player ledger-player ${playing?'is-playing':'is-closed'}" aria-label="${esc(p.name)} · ${state}">
 <header class="ledger-player-header">${avatar(p)}<div class="ledger-person"><div class="ledger-name-line"><h3><a href="#player" class="button ledger-name" data-action="profile" data-id="${p.id}" aria-label="View ${esc(p.name)}’s profile">${esc(p.name)}</a></h3></div></div><div class="ledger-state-column"><span class="ledger-play-state ${playing?'':'closed'}">${icon(playing?'table':'check')}${state}</span>${playing?`<span class="call-pill ${c.met?'met':''}" data-clock="${p.id}" aria-label="Minimum play time for ${esc(p.name)}"><strong>${c.met?'✓':c.text}</strong><small>${c.met?'Eligible':'left'}</small></span>`:''}</div></header>
 <dl class="ledger-money"><div><dt>Total buy-in</dt><dd>${money(p.buy)}</dd></div>${!playing?`<div><dt>Cash-out stack</dt><dd>${money(p.out)}</dd></div>`:`<div class="ledger-unknown"><dt>Poker result</dt><dd>In play</dd></div>`}
 ${!playing?`<div class="ledger-result"><dt>Poker result</dt><dd><strong class="${net>0?'positive':net<0?'negative':''}">${net===0?'₹0 · Break-even':signed(net)}</strong></dd></div>`:''}</dl>
 <div class="ledger-payment ${due?'outstanding':'complete'}">${icon(due?'receipt':'check')}<span>${paymentLabel}</span>${due?`<strong>${money(Math.abs(due))}</strong>`:''}</div>
 <div class="ledger-controls"><footer class="ledger-actions">${playing?button('Add money','rebuy','ledger-secondary',`data-id="${p.id}" aria-label="Add money for ${esc(p.name)}"`)+button('Cash out '+icon('arrow'),'cashout','ledger-primary',`data-id="${p.id}" aria-label="Cash out ${esc(p.name)}"`):button('View receipt '+icon('receipt'),'design-current-receipt','ledger-primary',`data-id="${p.id}" aria-label="View receipt for ${esc(p.name)}"`)+button('Edit stack','cashout','ledger-secondary',`data-id="${p.id}" aria-label="Edit stack for ${esc(p.name)}"`)}</footer>
 <details class="ledger-manage"><summary aria-label="Manage ${esc(p.name)}" title="Manage ${esc(p.name)}">${icon('more')}<span class="sr-only">Manage ${esc(p.name)}</span></summary><div><div class="ledger-more-actions">${button('Correct buy-in','player-options','text',`data-id="${p.id}"`)}${!playing?button('Return to play','reentry','text',`data-id="${p.id}"`):''}</div><dl class="ledger-payment-details"><div><dt>Buy-ins received</dt><dd>${money(p.received||0)}</dd></div><div><dt>Payouts recorded</dt><dd>${money(p.paid||0)}</dd></div></dl><p>Stacks and payments stay separate. Corrections need a reason.</p></div></details></div></article>`;
}

function table(){const b=balance();let list=players.filter(p=>(filter==='playing'?p.out===null:filter==='cashed'?p.out!==null:filter==='outstanding'?playerDue(p)!==0:true)&&p.name.toLowerCase().includes(tableQuery.toLowerCase()));list.sort((a,b)=>tableSort==='due'?Math.abs(playerDue(b))-Math.abs(playerDue(a)):a.name.localeCompare(b.name));const count=f=>players.filter(p=>f==='playing'?p.out===null:f==='cashed'?p.out!==null:f==='outstanding'?playerDue(p)!==0:true).length;return `<div class="table-heading"><div class="table-title-group">${head(esc(tableName),'Cash game · '+(tableBanker.name?'Banker: '+esc(tableBanker.name):'Banker details needed')+' · INR','')}</div><a class="button compact" href="#table-settings" aria-label="Table setup">${icon('table')}<span>Table setup</span></a></div><div class="table-summary-v2"><div><small>Table buy-ins</small><strong>${money(b.buy)}</strong></div><div class="minor"><small>Still in play</small><strong>${b.pending.length} <small style="display:inline">/ ${players.length}</small></strong></div><div class="minor"><small>Expected remaining stacks</small><strong>${money(b.difference)}</strong></div></div><div class="section-caption"><h2>Players <span class="ledger-roster-count">${players.length}</span></h2>${link('+ Add player','add-player','text compact')}</div><div class="table-toolbar"><input class="table-search" id="table-search" type="search" placeholder="Find someone at the table" aria-label="Search players at this table" value="${esc(tableQuery)}"><div class="pills" aria-label="Filter players">${[['all','Everyone'],['playing','Playing'],['cashed','Cashed out'],['outstanding','Payment due']].map(([id,l])=>`<button class="pill ${filter===id?'selected':''}" data-action="filter" data-value="${id}" aria-pressed="${filter===id}"><strong>${count(id)}</strong><span>${l}</span></button>`).join('')}</div></div><div class="player-grid" id="table-players">${list.map(playerCard).join('')||notice('No matching players. Try another name or filter.')}</div><div class="rake-tile"><div class="identity">${icon('receipt')}<div><strong>Rake · ${money(rakeTotal)}</strong><p>Recorded separately. Distributed outside the app.</p></div></div>${link('+ Add rake','rake-entry','compact')}</div><div class="table-end"><p>${b.pending.length} stacks still to enter.<br>Current stacks are unknown until cash-out.</p>${link('Review & end table','review','primary')}</div><div class="row">${link('Activity & corrections','activity','text compact')}${link('Minimum play · '+minimumHours+'h','table-settings','text compact')}</div>`}
function emptyTableDesign(){return head('A fresh table','Every good night starts with one person.','home')+`<div class="illustrated-note"><img src="assets/table-sculpture.svg" alt="Cards and chips ready for a new table"><div><h3>Your first seat is open</h3><p>Add someone from your saved players, or create a new player.</p></div></div><div class="card">${detail('Recorded buy-ins','₹0')}${detail('Players seated','0')}<p class="small">No money has been recorded. The first confirmed buy-in starts that player’s call-time clock.</p></div><div class="actions">${link('Add your first player','add-player','primary')}${link('Table settings','table-settings')}</div>`}
function rakeEntry(){return head('Add rake','Keep every addition traceable.','table')+`<form data-form="design-rake"><div class="card">${detail('Recorded rake',money(rakeTotal))}<p class="small">Distribution is handled outside Cash Out.</p></div><div class="field"><label for="rake-amount">Additional rake · ₹</label><input id="rake-amount" class="number-input" inputmode="decimal" value="${esc(rakeDraft)}" required></div><div class="actions"><button class="button primary" type="submit">Review rake addition</button></div></form>`}
function rakeReview(){const n=Number(rakeDraft)||0;return head('Check rake addition','Friday Night · cash game','rake-entry')+hero('Additional rake',money(n))+`<section class="card" style="margin-top:16px">${detail('Recorded rake',money(rakeTotal))}${detail('New rake total',money(rakeTotal+n))}</section>${notice('Rake reduces the amount available for player cash-outs. It is never included as a player in statistics.')}<div class="actions">${button('Record '+money(n)+' rake','design-rake-confirm','primary')}${link('Edit addition','rake-entry')}</div>`}
function sharePreview(){if(shareContext==='current'||shareContext==='receipt')return head('Ready to share','A private receipt for one player.',shareContext==='current'?'current-receipt':'receipt')+receiptDocument(receiptModel(shareContext==='current'))+`<div class="receipt-share-actions"><button class="button primary" data-action="native-share-receipt" disabled>Preparing image…</button>${button('Download PNG','download-receipt')}</div><p class="hint" id="receipt-share-status" role="status">Preparing a private image on this device. Nothing has been sent.</p>`;const current=shareContext==='current',p=current?players.find(p=>p.id===currentReceiptPlayerId):receiptPlayers[receiptId],due=current?playerDue(p):p.buy-p.received-p.out+p.paid;let content=shareContext==='table'?'Friday Regulars · 6 Nov 2026<br>Buy-ins ₹90,000 · cash-out stacks ₹88,200<br>Rake ₹1,800<br>Still to receive: Jamie Chen ₹6,200 from banker':shareContext==='tournament'?'Friday Cup · final standings<br>1. Jamie Chen · ₹7,500<br>2. Alex Morgan · ₹4,500<br>3. Taylor Reed · ₹3,000<br>Prizes recorded separately from payments':`${esc(p.name)} · buy-ins ${money(p.buy)}<br>Cash-out stack ${money(p.out||0)}<br>Poker result ${signed((p.out||0)-p.buy)}<br>${due<0?'Still to receive':due>0?'Still to pay':'Payment settled'} ${money(Math.abs(due))}`;return head('A receipt worth keeping','Review exactly what will leave your table.',current?'current-receipt':shareContext==='tournament'?'tournament-results':shareContext==='table'?'settlement':'receipt')+`<div class="illustrated-note"><img src="assets/receipt-cloud.svg" alt="Paper receipt with a check mark"><div><h3>Only the details you choose</h3><p>Names, results and relevant payments. Phone numbers and photos stay private.</p></div></div><section class="card"><span class="eyebrow">SHARE PREVIEW</span><h2 style="margin-top:12px">${shareContext==='tournament'?'Friday Cup':current?esc(tableName):'Friday Regulars'}</h2><p class="small" style="margin-top:10px">${content}</p></section><div class="actions">${button('Choose sharing method','design-share-method','primary')}${link('Back',current?'current-receipt':shareContext==='tournament'?'tournament-results':shareContext==='table'?'settlement':'receipt')}</div><p class="hint">No summary has been sent. Review is always before sharing.</p>`}

function csvImport(){return head('Bring your history along','Insights · phase two','insights')+`<div class="illustrated-note"><img src="assets/receipt-cloud.svg" alt="Illustrated saved record"><div><h3>Your records, with perspective</h3><p>Validate a Cash Out transaction CSV before generating insights.</p></div></div><form data-form="design-csv"><div class="field"><label for="insight-csv">Transaction CSV</label><input id="insight-csv" type="file" accept=".csv,text/csv" required></div>${notice('Check schema version, currency, exact amounts and table reconciliation. Invalid data must show row-specific errors. This design does not import files into live records.')}<div class="actions"><button class="button primary" type="submit">Validate CSV</button>${link('View saved-data insights','insights')}</div></form>`}
function saveState(state){const n=Number(amountDraft.amount)||2000,p=contacts.find(p=>p.id===amountDraft.id)||contacts[0];return head(state==='success'?'All accounted for.':state==='error'?'Your entry is still here.':'Recording your entry…','Friday Night · '+esc(p.name),'amount-review')+`<div class="illustrated-note"><img src="assets/receipt-cloud.svg" alt="Illustrated record and check mark"><div><h3>${state==='success'?'Entry recorded on this device':state==='error'?'No confirmed save yet':'Waiting for device storage'}</h3><p>${state==='success'?'Cloud backup is a separate status.':state==='error'?'Check storage and retry the same operation. Your amount and payment choice are kept.':'Keep this entry open until the device confirms it.'}</p></div></div>${hero('Amount',money(n))}<div class="actions">${state==='pending'?'<button class="button primary" disabled aria-busy="true">Saving on this device…</button>':state==='error'?link('Retry this entry','amount-review','primary'):link('Back to table','table','primary')}${state==='success'?link('View recorded activity','activity'):state==='error'?link('Edit entry','buy-in'):''}</div>`}

function tournamentRuleReview(){const c=tournamentConfig;return head('The rules, before the first hand.',esc(c.name)+' · review and lock','tournament-setup')+`<div class="tournament-banner"><div><span class="tag">One-table tournament</span><h2>${esc(c.name)}</h2><p>${c.seats} seats · INR</p></div><img src="assets/trophy.svg" alt="Tournament trophy"></div><section class="card">${detail('Starting chips',c.chips.toLocaleString('en-IN')+' per entry')}${detail('Entry amount',money(c.entry))}${detail('Level length',c.minutes+' minutes')}${detail('Registration & rebuys','Until '+esc(c.cutoff))}${detail('Add-on','₹500 · one per player')}${detail('Prize structure','Review before play')}</section>${notice('Rules are retained with the tournament. Changes after starting require a reason. Cash prizes and chip counts remain separate.')}<div class="actions">${button('Start tournament','design-start-tournament','primary')}${link('Edit rules','tournament-setup')}${link('Review prize structure','tournament-payouts')}</div>`}

function receiptActions(current=false){const m=receiptModel(current);return `<div class="receipt-action-bar">${m?.needsBanker?link('Add banker details','table-settings','primary'):button(icon('arrow')+'Share receipt',current?'design-share-current':'share-receipt','primary')}${m?.needsBanker?'':button(icon('download')+'Save PNG','download-receipt','receipt-save')}</div>`}
function currentReceipt(){if(!receiptModel(true))return emptyTableDesign();return head('Player receipt',esc(tableName)+' · current table','table')+receiptDocument(receiptModel(true))+receiptActions(true)+`<p class="hint">${receiptModel(true).needsBanker?'Add the banker’s name in Table settings before exporting. ':''}One player’s details. No phone numbers or photos.</p>`}



function blindAtLevel(level){const [small,big,ante]=[[25,50,0],[50,100,100],[75,150,150],[100,200,200],[150,300,300],[200,400,400],[300,600,600]][Math.max(0,Math.min(6,level-1))];return{small,big,ante}}

function homeActionTiles(){return `<div class="home-actions"><a class="action-tile" href="#new-table"><span class="tile-icon">${icon('plus')}</span><div><strong>Create a cash table</strong><small>Buy-ins, call times & cash-outs</small></div>${icon('arrow')}</a><a class="action-tile secondary-tile" href="#tournament-setup"><span class="tile-icon">${icon('cup')}</span><div><strong>Start a tournament</strong><small>One table. A proper occasion.</small></div>${icon('arrow')}</a></div>`}
